import { useRef } from 'react';

import { CONTEXT_ATOM_COLD_START_CACHE_KEYS } from '@onekeyhq/shared/src/consts/jotaiConsts';
import { readContextAtomSnapshotRaw } from '@onekeyhq/shared/src/storage/uiSnapshotCaches';
import { parseColdStartSnapshotRaw } from '@onekeyhq/shared/src/utils/coldStartCacheSnapshotUtils';
import {
  getSwapColdStartSelectedTokensFromSnapshot,
  isSwapColdStartAllNetworkContextNetworkId,
  normalizeSwapColdStartCacheSnapshot,
} from '@onekeyhq/shared/src/utils/swapColdStartCacheSnapshotUtils';
import type { ISwapSelectedTokensColdStartContext } from '@onekeyhq/shared/src/utils/swapColdStartCacheSnapshotUtils';
import { equalTokenNoCaseSensitive } from '@onekeyhq/shared/src/utils/tokenUtils';
import { ESwapTabSwitchType } from '@onekeyhq/shared/types/swap/types';
import type {
  ISwapNetwork,
  ISwapToken,
} from '@onekeyhq/shared/types/swap/types';

import {
  type ISwapBalanceDisplayCache,
  areSwapBalanceDisplayAccountKeysEquivalent,
  resolveSwapBalanceDisplayCacheEntry,
} from '../utils/swapBalanceDisplayCacheUtils';
import {
  buildSwapDefaultLimitSelectedTokens,
  buildSwapDefaultSelectedTokensFromHomeAccount,
} from '../utils/swapColdStartTokenCacheUtils';

const COLD_START_SCOPED_KEY_SEPARATOR = '::';
const SWAP_STORE_SCOPE_KEY = 'store:swap';
const ACCOUNT_SELECTOR_HOME_SCOPE_KEY = 'store:accountSelector@home';
const ACCOUNT_SELECTOR_SWAP_SCOPE_KEY = 'store:accountSelector@swap';

type IGlobalColdStartCache = typeof globalThis & {
  __ONEKEY_CTX_ATOM_SNAPSHOT__?: Record<string, unknown>;
};

type ISelectedAccountSnapshot = {
  walletId?: string;
  indexedAccountId?: string;
  othersWalletAccountId?: string;
  deriveType?: string;
  networkId?: string;
};

type ISelectedAccountsSnapshot = Record<
  string | number,
  ISelectedAccountSnapshot | undefined
>;

type IDisplayTokens = {
  fromToken?: ISwapToken;
  toToken?: ISwapToken;
};

function isSnapshotRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function buildContextAtomSnapshotKey({
  coldStartScopeKey,
  coldStartCacheKey,
}: {
  coldStartScopeKey: string;
  coldStartCacheKey: string;
}) {
  return `${coldStartScopeKey}${COLD_START_SCOPED_KEY_SEPARATOR}${coldStartCacheKey}`;
}

function getSnapshotValue<T>({
  snapshot,
  coldStartScopeKey,
  coldStartCacheKey,
}: {
  snapshot: Record<string, unknown>;
  coldStartScopeKey: string;
  coldStartCacheKey: string;
}) {
  return snapshot[
    buildContextAtomSnapshotKey({
      coldStartScopeKey,
      coldStartCacheKey,
    })
  ] as T | null | undefined;
}

function getSelectedAccountFromSnapshot({
  snapshot,
  coldStartScopeKey,
}: {
  snapshot: Record<string, unknown>;
  coldStartScopeKey: string;
}) {
  const selectedAccounts = getSnapshotValue<ISelectedAccountsSnapshot>({
    snapshot,
    coldStartScopeKey,
    coldStartCacheKey: CONTEXT_ATOM_COLD_START_CACHE_KEYS.selectedAccountsAtom,
  });
  return selectedAccounts?.[0] ?? selectedAccounts?.['0'];
}

function buildSelectedAccountKey(selectedAccount?: ISelectedAccountSnapshot) {
  const walletId = selectedAccount?.walletId ?? '';
  const accountId =
    selectedAccount?.indexedAccountId ??
    selectedAccount?.othersWalletAccountId ??
    '';
  const deriveType = selectedAccount?.deriveType ?? '';

  if (!walletId && !accountId) {
    return undefined;
  }

  return [walletId, accountId, deriveType].join('|');
}

function hasSwapSelectedTokenSnapshot(snapshot: Record<string, unknown>) {
  return Object.keys(snapshot).some(
    (key) =>
      key.endsWith(
        `::${CONTEXT_ATOM_COLD_START_CACHE_KEYS.swapSelectFromTokenAtom}`,
      ) ||
      key.endsWith(
        `::${CONTEXT_ATOM_COLD_START_CACHE_KEYS.swapSelectToTokenAtom}`,
      ),
  );
}

function hasSwapStockSelectedTokenSnapshot(snapshot: Record<string, unknown>) {
  return Object.keys(snapshot).some((key) =>
    key.endsWith(
      `::${CONTEXT_ATOM_COLD_START_CACHE_KEYS.swapStockSelectedTokenAtom}`,
    ),
  );
}

function isValidStockPayTokenDisplaySeed(token: ISwapToken | null | undefined) {
  return Boolean(
    token?.networkId &&
    token.contractAddress !== undefined &&
    token.symbol &&
    Number.isFinite(token.decimals) &&
    ['USDC', 'USDT'].includes(token.symbol.toUpperCase()) &&
    !token.isStock,
  );
}

function hasHomeSelectedAccountSnapshot(snapshot: Record<string, unknown>) {
  return Boolean(
    getSelectedAccountFromSnapshot({
      snapshot,
      coldStartScopeKey: ACCOUNT_SELECTOR_HOME_SCOPE_KEY,
    })?.networkId,
  );
}

function getColdStartSnapshotCandidatesFromGlobal() {
  const globalCache = globalThis as IGlobalColdStartCache;
  const snapshots: Record<string, unknown>[] = [];

  // The record as its namespace holds it, for a caller that runs before the
  // startup path published the parsed copy below.
  const snapshot = parseColdStartSnapshotRaw(readContextAtomSnapshotRaw());
  if (
    isSnapshotRecord(snapshot) &&
    (hasSwapSelectedTokenSnapshot(snapshot) ||
      hasSwapStockSelectedTokenSnapshot(snapshot) ||
      hasHomeSelectedAccountSnapshot(snapshot))
  ) {
    snapshots.push(snapshot);
  }

  if (
    isSnapshotRecord(globalCache.__ONEKEY_CTX_ATOM_SNAPSHOT__) &&
    (hasSwapSelectedTokenSnapshot(globalCache.__ONEKEY_CTX_ATOM_SNAPSHOT__) ||
      hasSwapStockSelectedTokenSnapshot(
        globalCache.__ONEKEY_CTX_ATOM_SNAPSHOT__,
      ) ||
      hasHomeSelectedAccountSnapshot(globalCache.__ONEKEY_CTX_ATOM_SNAPSHOT__))
  ) {
    snapshots.push(globalCache.__ONEKEY_CTX_ATOM_SNAPSHOT__);
  }

  return snapshots;
}

export function getSwapStockColdStartDisplayTokenFromGlobalSnapshot() {
  for (const snapshot of getColdStartSnapshotCandidatesFromGlobal()) {
    const normalizedSnapshot = normalizeSwapColdStartCacheSnapshot({
      ...snapshot,
    });
    const stockToken = getSnapshotValue<ISwapToken>({
      snapshot: normalizedSnapshot,
      coldStartScopeKey: SWAP_STORE_SCOPE_KEY,
      coldStartCacheKey:
        CONTEXT_ATOM_COLD_START_CACHE_KEYS.swapStockSelectedTokenAtom,
    });
    if (stockToken?.isStock) {
      return stockToken;
    }
  }

  return undefined;
}

export function getSwapStockPayTokenDisplayFromGlobalSnapshot({
  scope,
}: {
  scope: string;
}) {
  if (!scope) {
    return undefined;
  }
  for (const snapshot of getColdStartSnapshotCandidatesFromGlobal()) {
    const normalizedSnapshot = normalizeSwapColdStartCacheSnapshot({
      ...snapshot,
    });
    const payTokenDisplayByScope = getSnapshotValue<
      Record<string, ISwapToken | undefined>
    >({
      snapshot: normalizedSnapshot,
      coldStartScopeKey: SWAP_STORE_SCOPE_KEY,
      coldStartCacheKey:
        CONTEXT_ATOM_COLD_START_CACHE_KEYS.swapStockPayTokenDisplayAtom,
    });
    const token = payTokenDisplayByScope?.[scope];
    if (isValidStockPayTokenDisplaySeed(token)) {
      return token;
    }
  }

  return undefined;
}

function getSwapBalanceDisplayAccountKeyFromSnapshot({
  snapshot,
  tokenNetworkId,
}: {
  snapshot: Record<string, unknown>;
  tokenNetworkId: string;
}) {
  const cachedContext = getSnapshotValue<ISwapSelectedTokensColdStartContext>({
    snapshot,
    coldStartScopeKey: SWAP_STORE_SCOPE_KEY,
    coldStartCacheKey:
      CONTEXT_ATOM_COLD_START_CACHE_KEYS.swapSelectedTokensColdStartContextAtom,
  });
  if (cachedContext?.accountKey && cachedContext.networkId === tokenNetworkId) {
    return cachedContext.accountKey;
  }

  const homeSelectedAccount = getSelectedAccountFromSnapshot({
    snapshot,
    coldStartScopeKey: ACCOUNT_SELECTOR_HOME_SCOPE_KEY,
  });
  const homeAccountKey = buildSelectedAccountKey(homeSelectedAccount);
  if (
    homeAccountKey &&
    (homeSelectedAccount?.networkId === tokenNetworkId ||
      isSwapColdStartAllNetworkContextNetworkId(homeSelectedAccount?.networkId))
  ) {
    return homeAccountKey;
  }

  const swapSelectedAccount = getSelectedAccountFromSnapshot({
    snapshot,
    coldStartScopeKey: ACCOUNT_SELECTOR_SWAP_SCOPE_KEY,
  });
  const swapAccountKey = buildSelectedAccountKey(swapSelectedAccount);
  if (
    swapAccountKey &&
    swapSelectedAccount?.networkId === tokenNetworkId &&
    (!homeAccountKey || homeAccountKey === swapAccountKey)
  ) {
    return swapAccountKey;
  }
  return undefined;
}

export function getSwapBalanceDisplayEntryFromGlobalSnapshot({
  accountAddress,
  currentAccountKey,
  token,
}: {
  accountAddress?: string;
  currentAccountKey?: string;
  token?: ISwapToken;
}) {
  if (!token?.networkId) {
    return undefined;
  }
  for (const snapshot of getColdStartSnapshotCandidatesFromGlobal()) {
    const normalizedSnapshot = normalizeSwapColdStartCacheSnapshot({
      ...snapshot,
    });
    const snapshotAccountKey = getSwapBalanceDisplayAccountKeyFromSnapshot({
      snapshot: normalizedSnapshot,
      tokenNetworkId: token.networkId,
    });
    if (
      snapshotAccountKey &&
      (!currentAccountKey ||
        areSwapBalanceDisplayAccountKeysEquivalent(
          currentAccountKey,
          snapshotAccountKey,
        ))
    ) {
      const cache = getSnapshotValue<ISwapBalanceDisplayCache>({
        snapshot: normalizedSnapshot,
        coldStartScopeKey: SWAP_STORE_SCOPE_KEY,
        coldStartCacheKey:
          CONTEXT_ATOM_COLD_START_CACHE_KEYS.swapBalanceDisplayCacheAtom,
      });
      const entry = resolveSwapBalanceDisplayCacheEntry({
        accountAddress,
        accountKey: currentAccountKey ?? snapshotAccountKey,
        cache: cache ?? undefined,
        token,
      });
      if (entry) {
        return entry;
      }
    }
  }
  return undefined;
}

function shouldUseRawSwapSelectedTokens(snapshot: Record<string, unknown>) {
  const homeSelectedAccount = getSelectedAccountFromSnapshot({
    snapshot,
    coldStartScopeKey: ACCOUNT_SELECTOR_HOME_SCOPE_KEY,
  });
  const swapSelectedAccount = getSelectedAccountFromSnapshot({
    snapshot,
    coldStartScopeKey: ACCOUNT_SELECTOR_SWAP_SCOPE_KEY,
  });
  const cachedContext = getSnapshotValue<ISwapSelectedTokensColdStartContext>({
    snapshot,
    coldStartScopeKey: SWAP_STORE_SCOPE_KEY,
    coldStartCacheKey:
      CONTEXT_ATOM_COLD_START_CACHE_KEYS.swapSelectedTokensColdStartContextAtom,
  });
  const homeAccountKey = buildSelectedAccountKey(homeSelectedAccount);
  if (!homeSelectedAccount?.networkId || !homeAccountKey) {
    return false;
  }

  if (
    cachedContext?.accountKey === homeAccountKey &&
    cachedContext.networkId === homeSelectedAccount.networkId
  ) {
    return true;
  }

  const swapAccountKey = buildSelectedAccountKey(swapSelectedAccount);
  const isSameOwnerAllNetworksHome =
    isSwapColdStartAllNetworkContextNetworkId(homeSelectedAccount.networkId) &&
    homeAccountKey === swapAccountKey;
  if (!isSameOwnerAllNetworksHome) {
    return false;
  }

  if (!cachedContext) {
    return true;
  }

  return (
    cachedContext.accountKey === swapAccountKey &&
    cachedContext.networkId === swapSelectedAccount?.networkId
  );
}

function getRawSwapSelectedTokensFromSnapshot(
  snapshot: Record<string, unknown>,
): IDisplayTokens {
  if (!shouldUseRawSwapSelectedTokens(snapshot)) {
    return {};
  }

  return {
    fromToken:
      getSnapshotValue<ISwapToken>({
        snapshot,
        coldStartScopeKey: SWAP_STORE_SCOPE_KEY,
        coldStartCacheKey:
          CONTEXT_ATOM_COLD_START_CACHE_KEYS.swapSelectFromTokenAtom,
      }) ?? undefined,
    toToken:
      getSnapshotValue<ISwapToken>({
        snapshot,
        coldStartScopeKey: SWAP_STORE_SCOPE_KEY,
        coldStartCacheKey:
          CONTEXT_ATOM_COLD_START_CACHE_KEYS.swapSelectToTokenAtom,
      }) ?? undefined,
  };
}

function getDefaultSwapSelectedTokensFromHomeSnapshot(
  snapshot: Record<string, unknown>,
) {
  const homeSelectedAccount = getSelectedAccountFromSnapshot({
    snapshot,
    coldStartScopeKey: ACCOUNT_SELECTOR_HOME_SCOPE_KEY,
  });
  const defaultTokens = buildSwapDefaultSelectedTokensFromHomeAccount({
    homeSelectedAccount,
  });

  return {
    fromToken: defaultTokens?.fromToken,
    toToken: defaultTokens?.toToken,
  };
}

export function getSwapDefaultSelectedTokensFromGlobalHomeSnapshot({
  allNetworksOnly = false,
  swapType,
  swapNetworks,
}: {
  allNetworksOnly?: boolean;
  swapType?: ESwapTabSwitchType;
  swapNetworks?: ISwapNetwork[];
} = {}) {
  for (const snapshot of getColdStartSnapshotCandidatesFromGlobal()) {
    const homeSelectedAccount = getSelectedAccountFromSnapshot({
      snapshot,
      coldStartScopeKey: ACCOUNT_SELECTOR_HOME_SCOPE_KEY,
    });
    const shouldUseSnapshot =
      !allNetworksOnly ||
      isSwapColdStartAllNetworkContextNetworkId(homeSelectedAccount?.networkId);
    if (shouldUseSnapshot) {
      const defaultTokens = buildSwapDefaultSelectedTokensFromHomeAccount({
        homeSelectedAccount,
        swapType,
        swapNetworks,
      });
      if (defaultTokens?.fromToken?.symbol || defaultTokens?.toToken?.symbol) {
        return defaultTokens;
      }
    }
  }

  return undefined;
}

function hasDisplayToken(tokens: IDisplayTokens) {
  return Boolean(tokens.fromToken?.symbol || tokens.toToken?.symbol);
}

export function getSwapColdStartDisplayTokensFromGlobalSnapshot() {
  const displayTokens: {
    fromToken?: ISwapToken;
    toToken?: ISwapToken;
  } = {};

  for (const snapshot of getColdStartSnapshotCandidatesFromGlobal()) {
    const normalizedTokens =
      getSwapColdStartSelectedTokensFromSnapshot<ISwapToken>(snapshot);
    const rawTokens = getRawSwapSelectedTokensFromSnapshot(snapshot);
    const defaultTokens =
      getDefaultSwapSelectedTokensFromHomeSnapshot(snapshot);
    let candidateTokens: IDisplayTokens = defaultTokens;
    if (hasDisplayToken(normalizedTokens)) {
      candidateTokens = normalizedTokens;
    } else if (hasDisplayToken(rawTokens)) {
      candidateTokens = rawTokens;
    }

    if (!displayTokens.fromToken && candidateTokens.fromToken?.symbol) {
      displayTokens.fromToken = candidateTokens.fromToken;
    }
    if (!displayTokens.toToken && candidateTokens.toToken?.symbol) {
      displayTokens.toToken = candidateTokens.toToken;
    }
    if (displayTokens.fromToken && displayTokens.toToken) {
      break;
    }
  }

  return displayTokens;
}

export function resolveSwapDisplayToken({
  allowFallback,
  currentToken,
  fallbackToken,
  previousDisplayToken,
}: {
  allowFallback: boolean;
  currentToken?: ISwapToken;
  fallbackToken?: ISwapToken;
  previousDisplayToken?: ISwapToken;
}) {
  let nextToken: ISwapToken | undefined;
  if (currentToken?.symbol) {
    nextToken = currentToken;
  } else if (allowFallback && previousDisplayToken?.symbol) {
    nextToken = previousDisplayToken;
  } else if (allowFallback && fallbackToken?.symbol) {
    nextToken = fallbackToken;
  }
  if (!nextToken) {
    return undefined;
  }
  const matchingFallbackToken = equalTokenNoCaseSensitive({
    token1: fallbackToken,
    token2: nextToken,
  })
    ? fallbackToken
    : undefined;
  const matchingPreviousDisplayToken = equalTokenNoCaseSensitive({
    token1: previousDisplayToken,
    token2: nextToken,
  })
    ? previousDisplayToken
    : undefined;
  if (!matchingFallbackToken && !matchingPreviousDisplayToken) {
    return nextToken;
  }

  const matchingDisplayTokens = [
    matchingPreviousDisplayToken,
    matchingFallbackToken,
  ].filter((token): token is ISwapToken => Boolean(token));
  const distinctTokenLogoURI = matchingDisplayTokens.find(
    (token) =>
      token.logoURI &&
      token.logoURI !== token.networkLogoURI &&
      token.logoURI !== nextToken.logoURI,
  )?.logoURI;
  const nextLogoMatchesNetworkLogo = Boolean(
    nextToken.logoURI &&
    [
      nextToken.networkLogoURI,
      ...matchingDisplayTokens.map((token) => token.networkLogoURI),
    ].some((networkLogoURI) => networkLogoURI === nextToken.logoURI),
  );
  const logoURI =
    (nextLogoMatchesNetworkLogo ? distinctTokenLogoURI : undefined) ||
    nextToken.logoURI ||
    matchingPreviousDisplayToken?.logoURI ||
    matchingFallbackToken?.logoURI;
  const networkLogoURI =
    nextToken.networkLogoURI ||
    matchingPreviousDisplayToken?.networkLogoURI ||
    matchingFallbackToken?.networkLogoURI;
  if (
    logoURI === nextToken.logoURI &&
    networkLogoURI === nextToken.networkLogoURI
  ) {
    return nextToken;
  }

  return {
    ...nextToken,
    logoURI,
    networkLogoURI,
  };
}

export function useSwapColdStartDisplayTokens({
  fromToken,
  initialSelectedTokensSynced = false,
  swapType,
  toToken,
}: {
  fromToken?: ISwapToken;
  initialSelectedTokensSynced?: boolean;
  swapType?: ESwapTabSwitchType;
  toToken?: ISwapToken;
}) {
  const hasResolvedFromTokenRef = useRef(Boolean(fromToken?.symbol));
  const hasResolvedToTokenRef = useRef(Boolean(toToken?.symbol));
  const previousDisplayFromTokenRef = useRef<ISwapToken | undefined>(
    fromToken?.symbol ? fromToken : undefined,
  );
  const previousDisplayToTokenRef = useRef<ISwapToken | undefined>(
    toToken?.symbol ? toToken : undefined,
  );
  const coldStartDisplayTokensRef = useRef<
    | ReturnType<typeof getSwapColdStartDisplayTokensFromGlobalSnapshot>
    | undefined
  >(undefined);

  if (fromToken?.symbol) {
    hasResolvedFromTokenRef.current = true;
  }
  if (toToken?.symbol) {
    hasResolvedToTokenRef.current = true;
  }
  if (initialSelectedTokensSynced) {
    hasResolvedFromTokenRef.current = true;
    hasResolvedToTokenRef.current = true;
  }

  if (
    !coldStartDisplayTokensRef.current ||
    (!fromToken?.symbol &&
      !hasResolvedFromTokenRef.current &&
      !coldStartDisplayTokensRef.current.fromToken) ||
    (!toToken?.symbol &&
      !hasResolvedToTokenRef.current &&
      !coldStartDisplayTokensRef.current.toToken)
  ) {
    coldStartDisplayTokensRef.current =
      getSwapColdStartDisplayTokensFromGlobalSnapshot();
  }
  const coldStartDisplayTokens = coldStartDisplayTokensRef.current;
  const defaultDisplayTokens =
    swapType === ESwapTabSwitchType.LIMIT
      ? buildSwapDefaultLimitSelectedTokens()
      : undefined;

  const displayFromToken = resolveSwapDisplayToken({
    allowFallback:
      Boolean(defaultDisplayTokens?.fromToken) || !initialSelectedTokensSynced,
    currentToken: fromToken,
    fallbackToken:
      defaultDisplayTokens?.fromToken ?? coldStartDisplayTokens.fromToken,
    previousDisplayToken: previousDisplayFromTokenRef.current,
  });
  const displayToToken = resolveSwapDisplayToken({
    allowFallback:
      Boolean(defaultDisplayTokens?.toToken) || !initialSelectedTokensSynced,
    currentToken: toToken,
    fallbackToken:
      defaultDisplayTokens?.toToken ?? coldStartDisplayTokens.toToken,
    previousDisplayToken: previousDisplayToTokenRef.current,
  });
  if (displayFromToken?.symbol) {
    previousDisplayFromTokenRef.current = displayFromToken;
  }
  if (displayToToken?.symbol) {
    previousDisplayToTokenRef.current = displayToToken;
  }

  const displayTokens = {
    displayFromToken,
    displayToToken,
  };
  const isInitialFromTokenSelectionPending =
    !hasResolvedFromTokenRef.current && !displayTokens.displayFromToken?.symbol;
  const isInitialToTokenSelectionPending =
    !hasResolvedToTokenRef.current && !displayTokens.displayToToken?.symbol;

  return {
    ...displayTokens,
    isInitialFromTokenSelectionPending,
    isInitialToTokenSelectionPending,
  };
}
